              {' '}A claim needs an amount of 0.00 or more with up to two decimals, and a valid date.
            </span>
          )}
        </form>
        <ul>
          {claims.map((c) => (
            <ClaimRow
              key={c.id}
              sheet={sheet}
              user={user}
              claim={c}
              rate={rate}
              editing={editing === c.id}
              onEdit={() => open(c)}
              onCancel={cancel}
            />
          ))}
        </ul>
      </td>
    </>
  );
}

