  return claim.settledDue !== null ? hundredths(claim.settledDue) : dueCents(claim.amount, pct);
}

/** The due-total of a person's counted claims: the fixed dues of the settled ones added to the live
 *  ones' claimed at the grade's rate now; undefined when the grade has no rate. */
