  const live = counted(claims).filter((c) => c.settledDue === null);
  const liveDue = dueCents(claimed(live), pct);
  if (liveDue === undefined) return undefined;
  return counted(claims).reduce((sum, c) => (c.settledDue === null ? sum : sum + hundredths(c.settledDue)), liveDue);
}
